// Global land elevation grid, 0.25° equirectangular (1440 x 720, row 0 = 90°N). Built from AWS Terrain Tiles (Terrarium, zoom 4;
// sources incl. SRTM, ETOPO1, GMTED; https://registry.opendata.aws/terrain-tiles/). Byte per cell: 0 = ocean,
// 1 = land at/below sea level, else 1 + elevation/10 m (capped at 2,540 m).
const ELEV = { w: 1440, h: 720, b64: '', _a: null,
  arr() { if (!this._a) { const s = atob(this.b64), a = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) a[i] = s.charCodeAt(i); this._a = a; } return this._a; },
  at(lon, lat) { const a = this.arr(), x = Math.floor(((lon + 180) % 360 + 360) % 360 / 360 * this.w), y = Math.max(0, Math.min(this.h - 1, Math.floor((90 - lat) / 180 * this.h))); return a[y * this.w + x]; } };
